function b631_read(string $root, string $name): array
{
    $path = $root . '/storage/' . $name . '.json';
    $value = json_decode((string) file_get_contents($path), true);
    if (!is_array($value)) throw new RuntimeException("Invalid JSON: {$path}");
    return $value;
}

function b631_unique(array $values): array
{
    $out = [];
    foreach ($values as $value) if (is_scalar($value) && (string) $value !== '') $out[(string) $value] = true;
    $out = array_keys($out); sort($out, SORT_STRING); return $out;
}

function b631_depth(mixed $value): ?int
{
    return is_numeric($value) && (int) $value >= 1 && (int) $value <= 5 ? (int) $value : null;
}

function b631_ratio(int|float $a, int|float $b): float
{
    return $b > 0 ? round(($a / $b) * 100, 2) : 0.0;
}

function b631_hash(mixed $value): string
{
    return hash('sha256', json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION));
}

function b631_tax(array $q): array
{
    $t = is_array($q['taxonomy'] ?? null) ? $q['taxonomy'] : [];
    return ['board_id'=>(string)($t['board_id'] ?? $q['board'] ?? ''),'subject_id'=>(string)($t['subject_id'] ?? ''),'domain_id'=>(string)($t['domain_id'] ?? ''),'topic_id'=>(string)($t['topic_id'] ?? ''),'concept_id'=>(string)($t['concept_id'] ?? '')];
}

function b631_studies(mixed $qid, array $q, array $links): array
{
    $qid = (string) $qid;
    $ids = [];
    foreach ($links[$qid] ?? [] as $link) if (isset($link['material_id'])) $ids[] = $link['material_id'];
    if (isset($q['study_material_id'])) $ids[] = $q['study_material_id'];
    foreach (($q['study_material_ids'] ?? []) as $id) $ids[] = $id;
    return b631_unique($ids);
}

function b631_sources(mixed $qid, array $q, array $links): array
{
    $qid = (string) $qid;
    $ids = is_array($q['source_ids'] ?? null) ? $q['source_ids'] : [];
    foreach ($links[$qid] ?? [] as $link) foreach (($link['source_ids'] ?? []) as $id) $ids[] = $id;
    return b631_unique($ids);
}

function b631_matches(array $tax, array $mapping, array $area, string $nativeBoard): bool
{
    $candidate = $tax; $place = is_array($mapping['placement'] ?? null) ? $mapping['placement'] : [];
    if ($nativeBoard !== $tax['board_id']) {
        if (isset($mapping['subject_id'])) $candidate['subject_id'] = (string) $mapping['subject_id'];
        foreach (['domain_id','topic_id','concept_id'] as $key) if (isset($place[$key])) $candidate[$key] = (string) $place[$key];
    }
    foreach (($area['subjects'] ?? []) as $id) if ($candidate['subject_id'] === $id) return true;
    foreach (($area['domains'] ?? []) as $id) if ($candidate['domain_id'] === $id) return true;
    foreach (($area['topics'] ?? []) as $id) if ($candidate['topic_id'] === $id) return true;
    foreach (($area['concepts'] ?? []) as $id) if ($candidate['concept_id'] === $id) return true;
    foreach (($area['prefixes'] ?? []) as $prefix) if (str_starts_with($candidate['concept_id'], $prefix)) return true;
    return false;
}

function b631_risk(array $area): string
{
    $pool=(int)($area['effective_pool']??0); $min=(int)($area['min_concept_cohort']??0); $under10=(int)($area['under10']??0);
    if ($pool === 0 || $min <= 2) return 'CRITICAL';
    if ($min < 5 || $under10 >= 5) return 'HIGH';
    if ($min < 10 || $under10 > 0 || (int)($area['scenario_families']??0) < 5) return 'MODERATE';
    return 'LOW';
}

